// Add to RoomRosterContextValue interface:
selectedPlacements: Set<string>;
toggleSelection: (placementId: string) => void;
selectAll: () => void;
clearSelection: () => void;
isAllSelected: boolean;

story-context.context-state-pattern:

// Add to RoomRosterProvider state:
const [selectedPlacements, setSelectedPlacements] = useState<Set<string>>(new Set());

// Selection actions
const toggleSelection = useCallback((placementId: string) => {
  setSelectedPlacements(prev => {
    const next = new Set(prev);
    if (next.has(placementId)) {
      next.delete(placementId);
    } else {
      next.add(placementId);
    }
    return next;
  });
}, []);

const selectAll = useCallback(() => {
  setSelectedPlacements(new Set(students.map(s => s.placement_id)));
}, [students]);

const clearSelection = useCallback(() => {
  setSelectedPlacements(new Set());
}, []);

const isAllSelected = students.length > 0 && selectedPlacements.size === students.length;

// Clear selection when room/date/period changes
useEffect(() => {
  clearSelection();
}, [roomId, date, periodIndex, clearSelection]);

story-context.server-action-pattern:

// app/actions/daep/points.ts

interface BulkAddPointsInput {
  placementIds: string[];
  date: string;
  period: string;  // string, not number
  adjustment: number;  // +10, +5, -5, -10, -15
  notes?: string;
}

export async function bulkAddPoints(
  input: BulkAddPointsInput
): Promise<{ success: boolean; count: number; error?: string }> {
  const { userId, tenantId, displayName } = await checkDAEPStaffRole();
  const supabase = await createServerClient();

  const { placementIds, date, period, adjustment, notes } = input;

  // Validate adjustment is one of the allowed values
  const allowedAdjustments = [10, 5, -5, -10, -15];
  if (!allowedAdjustments.includes(adjustment)) {
    return { success: false, count: 0, error: 'Invalid adjustment value' };
  }

  // Build insert records (matching existing createPointAdjustment pattern)
  const entries = placementIds.map(placementId => ({
    tenant_id: tenantId,
    placement_id: placementId,
    date,
    period,
    points_earned: adjustment,  // column is 'points_earned', not 'adjustment'
    is_base_points: false,      // required: bulk actions are adjustments
    notes: notes || `Bulk: ${adjustment > 0 ? '+' : ''}${adjustment} points`,
    entered_by: userId,
    approval_status: 'approved',
    public: true,
  }));

  // INSERT (not upsert - multiple entries per period are allowed)
  const { error } = await supabase
    .from('daep_daily_points')
    .insert(entries);

  if (error) {
    console.error('Error creating bulk points:', error);
    return { success: false, count: 0, error: 'Failed to save bulk points' };
  }

  // Audit log for bulk action
  await logPointsAuditEvent(
    supabase,
    'points.bulk_adjustment',
    userId,
    placementIds[0], // Primary target
    `Bulk ${adjustment >= 0 ? '+' : ''}${adjustment} to ${placementIds.length} students`,
    tenantId,
    {
      date,
      period,
      adjustment,
      notes,
      affected_count: placementIds.length,
      placement_ids: placementIds,
      entered_by_name: displayName,
    }
  );

  revalidatePath('/daep/rooms');
  return { success: true, count: placementIds.length };
}

existing-code-snippets.snippet:

async function checkDAEPStaffRole(): Promise<DAEPStaffInfo> {
  const user = await currentUser();
  if (!user) throw new Error('Unauthorized');

  const supabase = await createServerClient();
  const { data: profile, error } = await supabase
    .from('user_profiles')
    .select('role, tenant_id, active_tenant_id, display_name')
    .eq('id', user.id)
    .single();

  if (error || !profile) {
    throw new Error('User profile not found');
  }

  const daepRoles = [
    'super_admin',
    'district_admin',
    'daep_admin_l1',
    'daep_admin_l2',
    'daep_staff',
  ];

  if (!daepRoles.includes(profile.role)) {
    throw new Error('Insufficient permissions. Only DAEP staff can manage points.');
  }

  const effectiveTenantId = profile.active_tenant_id || profile.tenant_id;
  if (!effectiveTenantId) {
    throw new Error('No tenant assigned');
  }

  return {
    userId: user.id,
    role: profile.role,
    tenantId: effectiveTenantId,
    displayName: profile.display_name || user.firstName || 'Staff',
  };
}


async function logPointsAuditEvent(
  supabase: Awaited<ReturnType<typeof createServerClient>>,
  eventType: string,
  actorId: string,
  targetId: string,
  action: string,
  tenantId: string,
  details?: Record<string, unknown>
): Promise<void> {
  try {
    await supabase.from('admin_audit_log').insert({
      event_type: eventType,
      actor_id: actorId,
      target_id: targetId,
      action,
      tenant_id: tenantId,
      module: 'daep_management',
      details,
    });
  } catch (error) {
    console.error('Failed to log points audit event:', error);
  }
}
